escena.anim:
F(id+"-ph", {y:60, opacity:0}, {y:0, opacity:1, duration:.45, ease:"power3.out"}, c.t0);
F(id+"-bat", {x:80, opacity:0}, {x:0, opacity:1, duration:.4, ease:"power3.out"}, c.t0+.15);
F(id+"-pct", {opacity:0}, {opacity:1, duration:.3}, c.t0+.3);
const dt = Math.max(.42, (c.t1-c.t0-.8)/3.2);
for (let k=2;k>=0;k--){
  const t = c.t0+.45+(2-k)*dt;
  F(id+"-fing", {opacity:0, x:0, y:0}, {opacity:1, duration:.08}, t);
  F(id+"-fing", {y:0}, {y:-520, duration:dt*.75, ease:"power2.in"}, t+.05);
  F(id+"-c"+k, {y:0, rotation:0, opacity:1}, {y:-1150, rotation:-8+k*6, opacity:.0, duration:dt*.8, ease:"power2.in"}, t+.05);
  F(id+"-fing", {opacity:1}, {opacity:0, duration:.08}, t+dt*.78);
}
F(id+"-glow", {scale:1, transformOrigin:"50% 50%"}, {scale:1.15, duration:c.t1-c.t0, ease:"sine.inOut"}, c.t0);

F(id+"-bb", {scale:.6, opacity:0, transformOrigin:"50% 50%"}, {scale:1, opacity:1, duration:.35, ease:"back.out(1.8)"}, c.t0);
F(id+"-p", {opacity:0, y:20}, {opacity:1, y:0, duration:.3}, c.t0+.15);
F(id+"-bb", {x:0}, {x:14, duration:.06, yoyo:true, repeat:5}, cue(0)-.05);
F(id+"-stamp", {opacity:0, scale:1.8, rotation:-14, transformOrigin:"50% 50%"}, {opacity:1, scale:1, rotation:-6, duration:.22, ease:"power4.in"}, cue(0));

F(id+"-ph", {scale:1, opacity:1, transformOrigin:"50% 50%"}, {scale:1.04, duration:.6, ease:"sine.inOut"}, c.t0);
const tz = Math.max(c.t0+.9, cue(0)+.3);
F(id+"-ph", {scale:1.04, opacity:1}, {scale:3.6, opacity:0, duration:.55, ease:"power3.in"}, tz);
F(id+"-chip", {scale:.4, opacity:0, transformOrigin:"50% 50%"}, {scale:1, opacity:1, duration:.45, ease:"back.out(1.6)"}, tz+.4);
for (let k=0;k<7;k++) F(id+"-tr"+k, {strokeDashoffset:600}, {strokeDashoffset:0, duration:.7, ease:"power2.out"}, tz+.55+k*.06);
F(id+"-glow", {scale:1, transformOrigin:"50% 50%"}, {scale:1.25, duration:c.t1-c.t0, ease:"sine.inOut"}, c.t0);

F(id+"-card", {y:-500, rotation:-10, transformOrigin:"50% 50%"}, {y:0, rotation:0, duration:.5, ease:"power3.out"}, c.t0);
for (let k=0;k<3;k++) F(id+"-d"+k, {x:-700}, {x:0, duration:.45, ease:"power3.out"}, c.t0+.1+k*.08);
const tf = cue(0);
F(id+"-ice", {opacity:0}, {opacity:.55, duration:.5}, tf);
for (let k=0;k<9;k++) F(id+"-sn"+k, {opacity:0, scale:.2, transformOrigin:"50% 50%"}, {opacity:1, scale:1, duration:.3, ease:"back.out(2)"}, tf+k*.05);
F(id+"-z1", {opacity:0, y:20}, {opacity:1, y:0, duration:.3}, tf+.4);
F(id+"-z2", {opacity:0, y:20}, {opacity:1, y:0, duration:.3}, tf+.6);
const tg = Math.max(tf+.9, cue(1));
F([id+"-card", id+"-ice"], {y:0, scale:1, transformOrigin:"50% 50%"}, {y:470, scale:.42, duration:.6, ease:"power3.inOut"}, tg);
for (let k=0;k<9;k++) F(id+"-sn"+k, {opacity:1}, {opacity:0, duration:.3}, tg);
F([id+"-z1", id+"-z2"], {opacity:1}, {opacity:0, duration:.2}, tg);
F(id+"-d0", {x:0}, {x:0, duration:.01}, tg);

for (let k=0;k<3;k++) F(id+"-f"+k, {y:-60, opacity:0}, {y:0, opacity:1, duration:.35, ease:"power3.out"}, c.t0+k*.08);
for (let k=0;k<3;k++) F(id+"-f"+k, {y:0}, {y:-10, duration:.9, yoyo:true, repeat:3, ease:"sine.inOut"}, c.t0+.5+k*.2);
F(id+"-g", {opacity:0, y:40}, {opacity:1, y:0, duration:.35}, c.t0+.1);
F(id+"-needle", {rotation:-88, svgOrigin:"540 1300"}, {rotation:-78, svgOrigin:"540 1300", duration:.6, ease:"power2.out"}, c.t0+.3);
F(id+"-needle", {rotation:-78, svgOrigin:"540 1300"}, {rotation:-82, svgOrigin:"540 1300", duration:.4, yoyo:true, repeat:5, ease:"sine.inOut"}, c.t0+.9);
F(id+"-arc", {strokeDashoffset:754}, {strokeDashoffset:705, duration:.6}, c.t0+.3);

for (let k=0;k<3;k++) F(id+"-e"+k, {opacity:0}, {opacity:1, duration:.3}, c.t0);
F(id+"-card", {y:420, scale:.42, transformOrigin:"50% 50%"}, {y:0, scale:1, duration:.45, ease:"power3.out"}, c.t0);
const tb = Math.max(c.t0+.7, cue(0)-.25);
F(id+"-fing", {opacity:0, y:0}, {opacity:1, duration:.08}, tb-.35);
F(id+"-fing", {y:0}, {y:-260, duration:.3, ease:"power2.in"}, tb-.28);
F(id+"-fing", {opacity:1}, {opacity:0, duration:.1}, tb);
F(id+"-card", {opacity:1}, {opacity:0, duration:.05}, tb);
for (let k=0;k<36;k++){
  const dx = ((k*53)%17-8)*42, dy = -200-((k*31)%11)*60;
  F(id+"-px"+k, {opacity:1, x:0, y:0, rotation:0, transformOrigin:"50% 50%"}, {opacity:0, x:dx, y:dy, rotation:(k%2?1:-1)*140, duration:.9, ease:"power2.out"}, tb+(k%6)*.012);
}
F(id, {x:0}, {x:12, duration:.05, yoyo:true, repeat:3}, tb);

F(id+"-ph", {y:50, opacity:0}, {y:0, opacity:1, duration:.35, ease:"power3.out"}, c.t0);
F(id+"-bat", {opacity:0}, {opacity:1, duration:.3}, c.t0+.1);
const tr = Math.max(c.t0+.5, cue(0)-.6), dur = Math.max(1.2, c.t1-tr-.2);
F(id+"-ring", {strokeDashoffset:691}, {strokeDashoffset:0, duration:dur, ease:"power1.inOut"}, tr);
F(id+"-g1", {rotation:0, transformOrigin:"50% 50%"}, {rotation:360, duration:dur, ease:"none"}, tr);
F(id+"-g2", {rotation:0, transformOrigin:"50% 50%"}, {rotation:-420, duration:dur, ease:"none"}, tr);
F(id+"-batf", {scaleX:1, transformOrigin:"0% 50%"}, {scaleX:.55, duration:dur, ease:"power1.in"}, tr);
F(id+"-batf", {fill:"#4ADE80"}, {fill:"#FFB547", duration:dur}, tr);
for (let k=0;k<4;k++){
  for (let r=0;r<3;r++){
    const t = tr + r*(dur/3) + k*.1;
    F(id+"-b"+k, {opacity:0, x:0, y:0, scale:.6, transformOrigin:"50% 50%"}, {opacity:1, x:-260, y:-140, scale:1, duration:dur/3-.05, ease:"power1.in"}, t);
  }
}

F(id+"-L", {x:-500, opacity:0}, {x:0, opacity:1, duration:.4, ease:"power3.out"}, c.t0);
F(id+"-R", {x:500, opacity:0}, {x:0, opacity:1, duration:.4, ease:"power3.out"}, c.t0+.12);
const tw = c.t0+.6, dd = Math.max(1.2, c.t1-tw-.3);
F(id+"-cube", {scaleY:1, transformOrigin:"50% 100%"}, {scaleY:.0, duration:.5, ease:"power2.in"}, tw);
F(id+"-b1f", {scaleX:1, transformOrigin:"0% 50%"}, {scaleX:.94, duration:.5}, tw);
F(id+"-gr", {rotation:0, transformOrigin:"50% 50%"}, {rotation:540, duration:dd, ease:"none"}, tw);
F(id+"-b2f", {scaleX:1, transformOrigin:"0% 50%"}, {scaleX:.62, duration:dd, ease:"power1.in"}, tw);
F(id+"-b2f", {fill:"#4ADE80"}, {fill:"#FF6B6B", duration:dd}, tw);

F(id+"-q", {y:120, opacity:0, rotation:-3, transformOrigin:"50% 50%"}, {y:0, opacity:1, rotation:0, duration:.45, ease:"power3.out"}, c.t0);
F(id+"-hl", {attr:{width:0}}, {attr:{width:560}, duration:.45, ease:"power2.out"}, cue(0)-.1);
F(id+"-q", {scale:1}, {scale:1.04, duration:c.t1-c.t0, ease:"sine.inOut"}, c.t0);

F(id+"-q", {x:700, opacity:0, rotation:4, transformOrigin:"50% 50%"}, {x:0, opacity:1, rotation:0, duration:.45, ease:"power3.out"}, c.t0);
F(id+"-hl", {attr:{width:0}}, {attr:{width:620}, duration:.45, ease:"power2.out"}, cue(0)-.1);
F(id+"-q", {scale:1}, {scale:1.04, duration:c.t1-c.t0, ease:"sine.inOut"}, c.t0);

F(id+"-ph", {y:60, opacity:0}, {y:0, opacity:1, duration:.4, ease:"power3.out"}, c.t0);
F(id+"-spin", {rotation:0, svgOrigin:"540 930"}, {rotation:720, svgOrigin:"540 930", duration:c.t1-c.t0, ease:"none"}, c.t0);
const ts = Math.max(c.t0+.8, cue(0)+.25);
F(id+"-ph", {y:0, opacity:1}, {y:-1300, opacity:0, duration:.5, ease:"power3.in"}, ts);
F(id+"-ok", {opacity:0, scale:.3, transformOrigin:"50% 50%"}, {opacity:1, scale:1, duration:.35, ease:"back.out(2)"}, ts+.4);

F(id+"-p1", {x:-400, opacity:0}, {x:0, opacity:1, duration:.4, ease:"power3.out"}, c.t0);
F(id+"-p2", {x:400, opacity:0}, {x:0, opacity:1, duration:.4, ease:"power3.out"}, c.t0+.1);
const tp = c.t0+.6;
F(id+"-trail", {opacity:0}, {opacity:.8, duration:.3}, tp);
F(id+"-plane", {x:0, y:0, rotation:0, transformOrigin:"50% 50%"}, {x:390, y:-20, rotation:20, duration:.9, ease:"power2.inOut"}, tp);
F(id+"-plane", {opacity:1}, {opacity:0, duration:.15}, tp+.9);
F(id+"-p2", {scale:1, transformOrigin:"50% 50%"}, {scale:1.06, duration:.15, yoyo:true, repeat:1}, tp+.95);
